window.AUTH=window.AUTH||{};window.AUTH["17-765"]={"d":"17-765","id":"2018/17-765","n":"United States v. Stitt","briefs":[{"k":"petitioner","label":"Brief of petitioner United States","date":"2018-06-26","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/51424/20180626164915138_17-765tsUnitedStates.pdf","side":"pet","n":33},{"k":"respondent","label":"Brief of respondent Jason Daniel Sims (in 17-766)","date":"2018-08-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/59469/20180814163051174_1%20-%20Sims%20-%20Brief%20for%20Respondent.pdf","side":"res","n":60},{"k":"respondent","label":"Brief of respondent Victor Stitt, II","date":"2018-08-14","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/59388/20180814133144856_Brief.pdf","side":"res","n":42},{"k":"reply","label":"Reply of petitioner United States","date":"2018-09-13","url":"https://www.supremecourt.gov/DocketPDF/17/17-765/63669/20180913164113063_17-765rbUnitedStates.pdf","side":"pet","n":26}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-765_2co3.pdf","tr":true,"items":[{"t":"case","label":"Central Va. Cmty. Coll. v. Katz","cite":"546 U.S. 356","y":2006,"id":"2005/04-885","sc":1,"sum":"The Court ruled that states cannot invoke sovereign immunity as a defense in bankruptcy proceedings. Rather than ruling on the power of Congress under the Bankruptcy Clause to waive states' immunity, as the bankruptcy court did, the Court held that ratification of the Clause itself involved a subordination of state sovereign immunity.","sumSrc":"Oyez","by":{"0":"34"}},{"t":"case","label":"Collins v. Virginia","cite":"138 S. Ct. 1663","y":2018,"id":"2017/16-1027","sc":1,"sum":"The Court held that a police officer cannot, under the Fourth Amendment, enter private property in order to conduct a warrantless search of a vehicle parked a few feet from the house.","sumSrc":"Oyez","by":{"0":"27","3":"13"}},{"t":"case","label":"Descamps v. United States","cite":"570 U.S. 254","y":2013,"id":"2012/11-9540","sc":1,"sum":"The Court held that it was improper to apply the categorical approach in which the courts apply elements of a prior conviction with elements of a generic crime in order to enhance a sentence under the ACCA.","sumSrc":"Oyez","by":{"0":"6","1":"3, 30, 37, 40","2":"23, 29, 33","3":"19"}},{"t":"case","label":"Favro v. State","cite":"46 S.W. 932","y":1898,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W./46/932/","sum":"Observing that by 1984, “the consensus of the state courts * * * was that tents and vehicles designed and used for human accommodation count as dwellings” that may be burglarized.","sumSrc":"brief:0","by":{"0":"19"}},{"t":"case","label":"Gonzales v. Duenas-Alvarez","cite":"549 U.S. 183","y":2007,"id":"2006/05-1629","sc":1,"sum":"The Court ruled unanimously that aiding and abetting a theft qualifies as a \"theft offense\" for purposes of the Immigration and Nationality Act. The opinion by Justice Stephen Breyer held that the common law had done away with all distinctions between \"principals\" and \"aiders and abettors\" of theft crimes.","sumSrc":"Oyez","by":{"0":"8, 36","1":"10, 34","2":"2, 20, 23"}},{"t":"case","label":"Johnson v. United States","cite":"135 S. Ct. 2551","y":2015,"id":"2014/13-7120","sc":1,"sum":"The Court determined that the residual clause of the Armed Criminal Career Act is unconstitutionally vague.","sumSrc":"Oyez","by":{"0":"7","1":"1","2":"3, 28, 31, 32"}},{"t":"case","label":"Kanaras v. State","cite":"460 A.2d 61","y":1983,"court":"Md. Ct. Spec. App.","url":"https://www.courtlistener.com/c/A.2d/460/61/","by":{"0":"19"}},{"t":"case","label":"Mathis v. United States","cite":"136 S. Ct. 2243","y":2016,"id":"2015/15-6092","sc":1,"op":5,"ar":9,"sum":"The Court determined that a state crime cannot qualify as a predicate offense under the Armed Career Criminal Act (ACCA) if the elements of the state offense are broader than those of a listed generic offense based on an “elements-only inquiry,” not a modified categorical approach.","sumSrc":"Oyez","by":{"0":"6, 8, 36","1":"passim","2":"passim","3":"14, 19"}},{"t":"case","label":"Nijhawan v. Holder","cite":"557 U.S. 29","y":2009,"id":"2008/08-495","sc":1,"sum":"The Court found that when an alien is convicted of conspiracy and held responsible for causing more than $10,000 in damages, the statute requirement used by the Immigration and Nationality Act (INA) to deport the alien is satisfied, even if the $10,000 is not established by a jury.","sumSrc":"Oyez","by":{"0":"8, 36","2":"2, 20, 23"}},{"t":"case","label":"People v. Netznik","cite":"383 N.E.2d 640","y":1978,"court":"Ill. App. Ct.","url":"https://www.courtlistener.com/c/N.E.2d/383/640/","by":{"0":"19"}},{"t":"case","label":"People v. Winhoven","cite":"237 N.W.2d 540","y":1975,"court":"Mich. Ct. App.","url":"https://www.courtlistener.com/c/N.W.2d/237/540/","by":{"0":"19"}},{"t":"case","label":"Reiter v. Sonotone Corp.","cite":"442 U.S. 330","y":1979,"id":"1978/78-690","sc":1,"sum":"Consumers who pay a higher price for goods purchased for personal use as a result of antitrust violations sustain an injury in their \"property\" within the meaning of § 4.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"33","1":"16, 33"}},{"t":"case","label":"Richardson v. State","cite":"888 S.W.2d 822","y":1994,"court":"Tex. Crim. App.","url":"https://www.courtlistener.com/c/S.W.2d/888/822/","by":{"0":"35"}},{"t":"case","label":"Shepard v. United States","cite":"544 U.S. 13","y":2005,"id":"2004/03-9168","sc":1,"ar":1,"sum":"The Court held that while a guilty plea could qualify as a predicate offense under the ACCA, courts may only look to the following when determining if that plea admitted to generic burglary: the terms of the charging document, the terms of a plea agreement, or a judicial record in which the defendant confirmed the factual basis for the plea (such as conversation between defendant and judge).","sumSrc":"Oyez","by":{"0":"6, 8, 36, 38","1":"passim","2":"passim","3":"14"}},{"t":"case","label":"Smith v. United States","cite":"877 F.3d 720","y":2017,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/877/720/","op":1,"by":{"0":"22, 31","1":"23, 24","2":"23, 24"}},{"t":"case","label":"State v. Pierre","cite":"320 So. 2d 185","y":1975,"court":"La.","url":"https://www.courtlistener.com/c/So.%202d/320/185/","by":{"0":"24"}},{"t":"case","label":"Taylor v. United States","cite":"495 U.S. 575","y":1990,"id":"1989/88-7194","sc":1,"op":6,"sum":"Noting that some States “define burglary more broadly” than generic burglary by, for example, “including places, such as automobiles and vending machines, other than buildings”.","sumSrc":"opinion","by":{"0":"passim","1":"passim","2":"passim","3":"passim"}},{"t":"case","label":"United States v. Grisel","cite":"488 F.3d 844","y":2007,"url":"https://www.courtlistener.com/c/F.3d/488/844/","op":1,"by":{"0":"23, 37","1":"34","2":"22, 23, 32"}},{"t":"case","label":"United States v. Herrold","cite":"883 F.3d 517","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/883/517/","sum":"Reasoning that “excluding a dwelling on the basis of whether it has (or, at some time, had) wheels” would be “invoking one of those very ‘arcane technicalities’ ” of the common-law that Taylor rejected.","sumSrc":"brief:0","by":{"0":"29, 30, 31, 32, 36","2":"passim"}},{"t":"case","label":"United States v. Lamb","cite":"847 F.3d 928","y":2017,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/847/928/","by":{"0":"13","2":"22"}},{"t":"case","label":"United States v. Leonard","cite":"868 F.2d 1393","y":1989,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/868/1393/","by":{"0":"35"}},{"t":"case","label":"United States v. Nance","cite":"481 F.3d 882","y":2007,"url":"https://www.courtlistener.com/c/F.3d/481/882/","by":{"0":"7"}},{"t":"case","label":"United States v. Priddy","cite":"808 F.3d 676","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/808/676/","by":{"0":"7"}},{"t":"case","label":"United States v. Rivera-Oros","cite":"590 F.3d 1123","y":2009,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/590/1123/","by":{"0":"27","3":"11"}},{"t":"case","label":"United States v. Spring","cite":"80 F.3d 1450","y":1996,"url":"https://www.courtlistener.com/c/F.3d/80/1450/","op":2,"sum":"Noting the greater risk of confrontation in a mobile home or camper, where “it is more difficult for the burglar to enter or escape unnoticed”.","sumSrc":"opinion","by":{"0":"27","2":"23, 24","3":"13"}},{"t":"case","label":"Will v. Michigan Dep’t of State Police","cite":"491 U.S. 58","y":1989,"id":"1988/87-1207","sc":1,"sum":"Neither States nor state officials acting in their official capacities are \"persons\" within meaning of § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"0":"27"}},{"t":"law","label":"Pub. L. No. 98-473","url":"https://www.govinfo.gov/link/statute/98/2185","by":{"0":"3, 25"}},{"t":"usc","label":"18 U.S.C. § 924","url":"https://www.law.cornell.edu/uscode/text/18/924","subs":["(e)(2)(B)","(e)(2)(B)(ii)","(a)(2)","(e)","(e)(1)","(g)"],"stext":{"head":"§924. Penalties","paras":[[0,"(a)(1) Except as otherwise provided in this subsection, subsection (b), (c), (f), or (p) of this section, or in section 929, whoever—"],[1,"(A) knowingly makes any false statement or representation with respect to the information required by this chapter to be kept in the records of a person licensed under this chapter or in applying for any license or exemption or relief from disability under the provisions of this chapter;"],[1,"(B) knowingly violates subsection (a)(4), (f), (k), or (q) of section 922;"],[1,"(C) knowingly imports or brings into the United States or any possession thereof any firearm or ammunition in violation of section 922(l); or"],[1,"(D) willfully violates any other provision of this chapter,"],[0,"shall be fined under this title, imprisoned not more than five years, or both."],[0,"(2) Whoever knowingly violates subsection (a)(6), (h), (i), (j), or (o) of section 922 shall be fined as provided in this title, imprisoned not more than 10 years, or both."],[0,"(3) Any licensed dealer, licensed importer, licensed manufacturer, or licensed collector who knowingly—"],[1,"(A) makes any false statement or representation with respect to the information required by the provisions of this chapter to be kept in the records of a person licensed under this chapter, or"],[1,"(B) violates subsection (m) of section 922,"],[0,"shall be fined under this title, imprisoned not more than one year, or both."],[0,"(4) Whoever violates section 922(q) shall be fined under this title, imprisoned for not more than 5 years, or both. Notwithstanding any other provision of law, the term of imprisonment imposed under this paragraph shall not run concurrently with any other term of imprisonment imposed under any other provision of law. Except for the authorization of a term of imprisonment of not more than 5 years made in this paragraph, for the purpose of any other law a violation of section 922(q) shall be deemed to be a misdemeanor."],[0,"(5) Whoever knowingly violates subsection (s) or (t) of section 922 shall be fined under this title, imprisoned for not more than 1 year, or both."],[0,"(6)(A)(i) A juvenile who violates section 922(x) shall be fined under this title, imprisoned not more than 1 year, or both, except that a juvenile described in clause (ii) shall be sentenced to probation on appropriate conditions and shall not be incarcerated unless the juvenile fails to comply with a condition of probation."],[0,"(ii) A juvenile is described in this clause if—"],[1,"(I) the offense of which the juvenile is charged is possession of a handgun or ammunition in violation of section 922(x)(2); and"],[1,"(II) the juvenile has not been convicted in any court of an offense (including an offense under section 922(x) or a similar State law, but not including any other offense consisting of conduct that if engaged in by an adult would not constitute an offense) or adjudicated as a juvenile delinquent for conduct that if engaged in by an adult would constitute an offense."],[0,"(B) A person other than a juvenile who knowingly violates section 922(x)—"],[1,"(i) shall be fined under this title, imprisoned not more than 1 year, or both; and"],[1,"(ii) if the person sold, delivered, or otherwise transferred a handgun or ammunition to a juvenile knowing or having reasonable cause to know that the juvenile intended to carry or otherwise possess or discharge or otherwise use the handgun or ammunition in the commission of a crime of violence, shall be fined under this title, imprisoned not more than 10 years, or both."],[0,"(7) Whoever knowingly violates section 931 shall be fined under this title, imprisoned not more than 3 years, or both."],[0,"(8) Whoever knowingly violates subsection (d) or (g) of section 922 shall be fined under this title, imprisoned for not more than 15 years, or both."],[0,"(b) Whoever, with intent to commit therewith an offense punishable by imprisonment for a term exceeding one year, or with knowledge or reasonable cause to believe that an offense punishable by imprisonment for a term exceeding one year is to be committed therewith, ships, transports, or receives a firearm or any ammunition in interstate or foreign commerce shall be fined under this title, or imprisoned not more than ten years, or both."],[0,"(c)(1)(A) Except to the extent that a greater minimum sentence is otherwise provided by this subsection or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries a firearm, or who, in furtherance of any such crime, possesses a firearm, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime—"],[1,"(i) be sentenced to a term of imprisonment of not less than 5 years;"],[1,"(ii) if the firearm is brandished, be sentenced to a term of imprisonment of not less than 7 years; and"],[1,"(iii) if the firearm is discharged, be sentenced to a term of imprisonment of not less than 10 years."],[0,"(B) If the firearm possessed by a person convicted of a violation of this subsection—"],[1,"(i) is a short-barreled rifle, short-barreled shotgun, or semiautomatic assault weapon, the person shall be sentenced to a term of imprisonment of not less than 10 years; or"],[1,"(ii) is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, the person shall be sentenced to a term of imprisonment of not less than 30 years."],[0,"(C) In the case of a violation of this subsection that occurs after a prior conviction under this subsection has become final, the person shall—"],[1,"(i) be sentenced to a term of imprisonment of not less than 25 years; and"],[1,"(ii) if the firearm involved is a machinegun or a destructive device, or is equipped with a firearm silencer or firearm muffler, be sentenced to imprisonment for life."],[0,"(D) Notwithstanding any other provision of law—"],[1,"(i) a court shall not place on probation any person convicted of a violation of this subsection; and"],[1,"(ii) no term of imprisonment imposed on a person under this subsection shall run concurrently with any other term of imprisonment imposed on the person, including any term of imprisonment imposed for the crime of violence or drug trafficking crime during which the firearm was used, carried, or possessed."],[0,"(2) For purposes of this subsection, the term \"drug trafficking crime\" means any felony punishable under the Controlled Substances Act (21 U.S.C. 801 et seq.), the Controlled Substances Import and Export Act (21 U.S.C. 951 et seq.), or chapter 705 of title 46."],[0,"(3) For purposes of this subsection the term \"crime of violence\" means an offense that is a felony and—"],[1,"(A) has as an element the use, attempted use, or threatened use of physical force against the person or property of another, or"],[1,"(B) that by its nature, involves a substantial risk that physical force against the person or property of another may be used in the course of committing the offense."],[0,"(4) For purposes of this subsection, the term \"brandish\" means, with respect to a firearm, to display all or part of the firearm, or otherwise make the presence of the firearm known to another person, in order to intimidate that person, regardless of whether the firearm is directly visible to that person."],[0,"(5) Except to the extent that a greater minimum sentence is otherwise provided under this subsection, or by any other provision of law, any person who, during and in relation to any crime of violence or drug trafficking crime (including a crime of violence or drug trafficking crime that provides for an enhanced punishment if committed by the use of a deadly or dangerous weapon or device) for which the person may be prosecuted in a court of the United States, uses or carries armor piercing ammunition, or who, in furtherance of any such crime, possesses armor piercing ammunition, shall, in addition to the punishment provided for such crime of violence or drug trafficking crime or conviction under this section—"],[1,"(A) be sentenced to a term of imprisonment of not less than 15 years; and"],[1,"(B) if death results from the use of such ammunition—"],[2,"(i) if the killing is murder (as defined in section 1111), be punished by death or sentenced to a term of imprisonment for any term of years or for life; and"],[2,"(ii) if the killing is manslaughter (as defined in section 1112), be punished as provided in section 1112."],[0,"(d)(1) Any firearm or ammunition involved in or used in any knowing violation of subsection (a)(4), (a)(6), (f), (g), (h), (i), (j), or (k) of section 922, or knowing importation or bringing into the United States or any possession thereof any firearm or ammunition in violation of section 922(l), or knowing violation of section 924, 932, or 933, or willful violation of any other provision of this chapter or any rule or regulation promulgated thereunder, or any violation of any other criminal law of the United States, or any firearm or ammunition intended to be used in any offense referred to in paragraph (3) of this subsection, where such intent is demonstrated by clear and convincing evidence, shall be subject to seizure and forfeiture, and all provisions of the Internal Revenue Code of 1986 relating to the seizure, forfeiture, and disposition of firearms, as defined in section 5845(a) of that Code, shall, so far as applicable, extend to seizures and forfeitures under the provisions of this chapter: Provided, That upon acquittal of the owner or possessor, or dismissal of the charges against him other than upon motion of the Government prior to trial, or lapse of or court termination of the restraining order to which he is subject, the seized or relinquished firearms or ammunition shall be returned forthwith to the owner or possessor or to a person delegated by the owner or possessor unless the return of the firearms or ammunition would place the owner or possessor or his delegate in violation of law. Any action or proceeding for the forfeiture of firearms or ammunition shall be commenced within one hundred and twenty days of such seizure."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/924?type=usc&year=mostrecent&link-type=html"},"op":2,"head":"§924. Penalties","tname":"Crimes and Criminal Procedure","by":{"0":"3, 3","1":"1, 9, 1, 1","2":"2, 7, 7, 10, 2","3":"1"}},{"t":"law","label":"Pub. L. No. 99-570","url":"https://www.govinfo.gov/link/statute/100/3207","by":{"0":"4","2":"8, 10-11","3":"3"}},{"t":"law","label":"and guideline—Continued: Firearm Owners’ Protection Act, Pub. L. No. 99-308","url":"https://www.govinfo.gov/link/statute/100/459","by":{"0":"3, 25","2":"7"}},{"t":"usc","label":"18 U.S.C. § 922","url":"https://www.law.cornell.edu/uscode/text/18/922","subs":["(g)(1)","(g)","(g)(9)"],"stext":{"head":"§922. Unlawful acts","paras":[[0,"(a) It shall be unlawful—"],[1,"(1) for any person—"],[2,"(A) except a licensed importer, licensed manufacturer, or licensed dealer, to engage in the business of importing, manufacturing, or dealing in firearms, or in the course of such business to ship, transport, or receive any firearm in interstate or foreign commerce; or"],[2,"(B) except a licensed importer or licensed manufacturer, to engage in the business of importing or manufacturing ammunition, or in the course of such business, to ship, transport, or receive any ammunition in interstate or foreign commerce;"],[1,"(2) for any importer, manufacturer, dealer, or collector licensed under the provisions of this chapter to ship or transport in interstate or foreign commerce any firearm to any person other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, except that—"],[2,"(A) this paragraph and subsection (b)(3) shall not be held to preclude a licensed importer, licensed manufacturer, licensed dealer, or licensed collector from returning a firearm or replacement firearm of the same kind and type to a person from whom it was received; and this paragraph shall not be held to preclude an individual from mailing a firearm owned in compliance with Federal, State, and local law to a licensed importer, licensed manufacturer, licensed dealer, or licensed collector;"],[2,"(B) this paragraph shall not be held to preclude a licensed importer, licensed manufacturer, or licensed dealer from depositing a firearm for conveyance in the mails to any officer, employee, agent, or watchman who, pursuant to the provisions of section 1715 of this title, is eligible to receive through the mails pistols, revolvers, and other firearms capable of being concealed on the person, for use in connection with his official duty; and"],[2,"(C) nothing in this paragraph shall be construed as applying in any manner in the District of Columbia, the Commonwealth of Puerto Rico, or any possession of the United States differently than it would apply if the District of Columbia, the Commonwealth of Puerto Rico, or the possession were in fact a State of the United States;"],[1,"(3) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector to transport into or receive in the State where he resides (or if the person is a corporation or other business entity, the State where it maintains a place of business) any firearm purchased or otherwise obtained by such person outside that State, except that this paragraph (A) shall not preclude any person who lawfully acquires a firearm by bequest or intestate succession in a State other than his State of residence from transporting the firearm into or receiving it in that State, if it is lawful for such person to purchase or possess such firearm in that State, (B) shall not apply to the transportation or receipt of a firearm obtained in conformity with subsection (b)(3) of this section, and (C) shall not apply to the transportation of any firearm acquired in any State prior to the effective date of this chapter;"],[1,"(4) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, to transport in interstate or foreign commerce any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity;"],[1,"(5) for any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) to transfer, sell, trade, give, transport, or deliver any firearm to any person (other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector) who the transferor knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the transferor resides; except that this paragraph shall not apply to (A) the transfer, transportation, or delivery of a firearm made to carry out a bequest of a firearm to, or an acquisition by intestate succession of a firearm by, a person who is permitted to acquire or possess a firearm under the laws of the State of his residence, and (B) the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(6) for any person in connection with the acquisition or attempted acquisition of any firearm or ammunition from a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, knowingly to make any false or fictitious oral or written statement or to furnish or exhibit any false, fictitious, or misrepresented identification, intended or likely to deceive such importer, manufacturer, dealer, or collector with respect to any fact material to the lawfulness of the sale or other disposition of such firearm or ammunition under the provisions of this chapter;"],[1,"(7) for any person to manufacture or import armor piercing ammunition, unless—"],[2,"(A) the manufacture of such ammunition is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) the manufacture of such ammunition is for the purpose of exportation; or"],[2,"(C) the manufacture or importation of such ammunition is for the purpose of testing or experimentation and has been authorized by the Attorney General;"],[1,"(8) for any manufacturer or importer to sell or deliver armor piercing ammunition, unless such sale or delivery—"],[2,"(A) is for the use of the United States, any department or agency of the United States, any State, or any department, agency, or political subdivision of a State;"],[2,"(B) is for the purpose of exportation; or"],[2,"(C) is for the purpose of testing or experimentation and has been authorized by the Attorney General; 1"],[1,"(9) for any person, other than a licensed importer, licensed manufacturer, licensed dealer, or licensed collector, who does not reside in any State to receive any firearms unless such receipt is for lawful sporting purposes."],[0,"(b) It shall be unlawful for any licensed importer, licensed manufacturer, licensed dealer, or licensed collector to sell or deliver—"],[1,"(1) any firearm or ammunition to any individual who the licensee knows or has reasonable cause to believe is less than eighteen years of age, and, if the firearm, or ammunition is other than a shotgun or rifle, or ammunition for a shotgun or rifle, to any individual who the licensee knows or has reasonable cause to believe is less than twenty-one years of age;"],[1,"(2) any firearm to any person in any State where the purchase or possession by such person of such firearm would be in violation of any State law or any published ordinance applicable at the place of sale, delivery or other disposition, unless the licensee knows or has reasonable cause to believe that the purchase or possession would not be in violation of such State law or such published ordinance;"],[1,"(3) any firearm to any person who the licensee knows or has reasonable cause to believe does not reside in (or if the person is a corporation or other business entity, does not maintain a place of business in) the State in which the licensee's place of business is located, except that this paragraph (A) shall not apply to the sale or delivery of any rifle or shotgun to a resident of a State other than a State in which the licensee's place of business is located if the transferee meets in person with the transferor to accomplish the transfer, and the sale, delivery, and receipt fully comply with the legal conditions of sale in both such States (and any licensed manufacturer, importer or dealer shall be presumed, for purposes of this subparagraph, in the absence of evidence to the contrary, to have had actual knowledge of the State laws and published ordinances of both States), and (B) shall not apply to the loan or rental of a firearm to any person for temporary use for lawful sporting purposes;"],[1,"(4) to any person any destructive device, machinegun (as defined in section 5845 of the Internal Revenue Code of 1986), short-barreled shotgun, or short-barreled rifle, except as specifically authorized by the Attorney General consistent with public safety and necessity; and"],[1,"(5) any firearm or armor-piercing ammunition to any person unless the licensee notes in his records, required to be kept pursuant to section 923 of this chapter, the name, age, and place of residence of such person if the person is an individual, or the identity and principal and local places of business of such person if the person is a corporation or other business entity."],[0,"Paragraphs (1), (2), (3), and (4) of this subsection shall not apply to transactions between licensed importers, licensed manufacturers, licensed dealers, and licensed collectors. Paragraph (4) of this subsection shall not apply to a sale or delivery to any research organization designated by the Attorney General."],[0,"(c) In any case not otherwise prohibited by this chapter, a licensed importer, licensed manufacturer, or licensed dealer may sell a firearm to a person who does not appear in person at the licensee's business premises (other than another licensed importer, manufacturer, or dealer) only if—"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/18/922?type=usc&year=mostrecent&link-type=html"},"head":"§922. Unlawful acts","tname":"Crimes and Criminal Procedure","by":{"0":"2, 3, 6, 11","1":"1, 3","3":"7"}},{"t":"case","label":"Alleyne v. United States","cite":"570 U.S. 99","y":2013,"id":"2012/11-9335","sc":1,"sum":"The Court found that a defendant cannot be found guilty of a claim not included in the indictment.","sumSrc":"Oyez","by":{"1":"43","3":"19"}},{"t":"case","label":"Almendarez-Torres v. United States","cite":"523 U.S. 224","y":1999,"id":"1997/96-6839","sc":1,"sum":"The Court held that subsection (b)(2) of 8 USC section 1326(a) is a penalty provision, which authorizes a court to increase the sentence for a recidivist, and does not define a separate crime. \"[W]e note that the relevant statutory subject matter is recidivism,\" wrote Justice Breyer, \"[t]hat subject matter -- prior commission of a serious crime -- is as typical a sentencing factor as one might imagine.\" Therefore, neither subsection (b)(2) nor the due process clause of the Fifth Amendment required that the government charge a prior aggravated felony conviction in the alien's indictment for the imposition of a sentence more than 2 years.","sumSrc":"Oyez","by":{"1":"7, 42","2":"7, 35","3":"18"}},{"t":"case","label":"Apprendi v. New Jersey","cite":"530 U.S. 466","y":2000,"id":"1999/99-478","sc":1,"ar":1,"sum":"The Court held that the Due Process Clause requires that any fact that increases the penalty for a crime beyond the prescribed statutory maximum, other than the fact of a prior conviction, must be submitted to a jury and proved beyond a reasonable doubt.","sumSrc":"Oyez","by":{"1":"40, 42, 43","3":"18, 19"}},{"t":"case","label":"Bell v. United States","cite":"349 U.S. 81","y":1955,"id":"scdb/1954-072","sc":1,"sum":"Petitioner committed but a single offense, and was not subject to cumulative punishment under the two counts.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Busic v. United States","cite":"446 U.S. 398","y":1980,"id":"1979/78-6020","sc":1,"sum":"Section 924 (c) may not be applied to a defendant who uses a firearm in the course of a felony that is proscribed by a statute which itself authorizes enhancement if a dangerous weapon is used. The sentence received by such a defendant may be enhanced only under the enhancement provision in the statute defining the felony he committed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Crandon v. United States","cite":"494 U.S. 152","y":1990,"id":"1989/88-931","sc":1,"sum":"Section 209(a) does not apply to a severance payment that is made to encourage the payee to accept Government employment, but is made before the payee becomes a Government employee.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Esquivel-Quintana v. Sessions","cite":"137 S. Ct. 1562","y":2017,"id":"2016/16-54","sc":1,"sum":"The Court determined that the crime of “unlawful sexual intercourse with a minor” as defined by California law cannot be categorically considered the aggravated felony of “sexual abuse of a minor” for the purpose of mandatory removal under the Immigration and Nationality Act (INA).","sumSrc":"Oyez","by":{"1":"21, 30","3":"3, 4, 9"}},{"t":"case","label":"Harris v. United States","cite":"536 U.S. 545","y":2002,"id":"2001/00-10666","sc":1,"sum":"The Court held that section 924(c)(1)(A) defines a single offense, in which brandishing a firearm is a sentencing factor to be found by the judge, not an offense element to be found by the jury.","sumSrc":"Oyez","by":{"1":"43"}},{"t":"case","label":"Hilton v. S.C. Pub. Rys. Comm’n","cite":"502 U.S. 197","y":1991,"id":"1991/90-848","sc":1,"sum":"FELA creates a cause of action against a state-owned railroad, enforceable in state court.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"16"}},{"t":"case","label":"Holbrook v. Healthport, Inc.","cite":"432 S.W.3d 593","y":2014,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/432/593/","by":{"1":"32"}},{"t":"case","label":"Hylton v. Sessions, ___ F.3d ___","cite":"2018 WL 3483561","y":2018,"court":"2d Cir. July 20","by":{"1":"34, 36"}},{"t":"case","label":"James v. United States","cite":"550 U.S. 192","y":2007,"id":"2006/05-9264","sc":1,"op":1,"sum":"The Court ruled 5-3 that attempted burglary is a \"violent felony\" for purposes of the Armed Career Criminal Act.","sumSrc":"Oyez","by":{"1":"22"}},{"t":"case","label":"Lozman v. City of Riviera Beach, Fla.","cite":"568 U.S. 115","y":2013,"id":"2012/11-626","sc":1,"sum":"The Court held that the definition of vessel under 1 U.S.C. §3 is too broad and not any floating structure is considered a vessel.","sumSrc":"Oyez","by":{"1":"13"}},{"t":"case","label":"Mellouli v. Holder","cite":"719 F.3d 995","y":2013,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/719/995/","by":{"1":"31"}},{"t":"case","label":"Mellouli v. Lynch","cite":"135 S. Ct. 1980","y":2015,"id":"2014/13-1034","sc":1,"sum":"The Government must prove the connection between a state drug paraphernalia conviction and a substance listed in the Controlled Substances Act to trigger deportability under the Immigration and Nationality Act.","sumSrc":"Oyez","by":{"1":"30, 31, 37"}},{"t":"case","label":"Mendieta-Robles v. Gonzales","cite":"226 F. App’x 564","y":2007,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/226/564/","by":{"1":"35"}},{"t":"case","label":"Missouri v. Frye","cite":"566 U.S. 134","y":2012,"id":"2011/10-444","sc":1,"op":1,"sum":"The Court held that the Sixth Amendment requires defense attorneys to communicate formal plea offers from the prosecution.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Moncrieffe v. Holder","cite":"569 U.S. 184","y":2013,"id":"2012/11-702","sc":1,"sum":"The Court found that distribution of small amounts of marijuana does not constitute an aggravated felony and thus, does not require deportation of the distributor.","sumSrc":"Oyez","by":{"1":"37"}},{"t":"case","label":"Nat’l Home Centers, Inc. v. Coleman","cite":"283 S.W.3d 218","y":2008,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.3d/283/218/","by":{"1":"32"}},{"t":"case","label":"Nunez v. Holder","cite":"594 F.3d 1124","y":2010,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/594/1124/","by":{"1":"38"}},{"t":"case","label":"Ramos v. U.S. Att’y Gen.","cite":"709 F.3d 1066","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/709/1066/","by":{"1":"35"}},{"t":"case","label":"Rivers v. Roadway Exp., Inc.","cite":"511 U.S. 298","y":1994,"id":"1993/92-938","sc":1,"sum":"Section 101 does not apply to a case that arose before it was enacted.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"case","label":"Singh v. U.S. Att’y Gen.","cite":"839 F.3d 273","y":2016,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/839/273/","by":{"1":"35"}},{"t":"case","label":"State v. Reeves","cite":"574 S.W.2d 647","y":1978,"court":"Ark.","url":"https://www.courtlistener.com/c/S.W.2d/574/647/","by":{"1":"33"}},{"t":"case","label":"State v. Ryun","cite":"549 S.W.2d 141","y":1977,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.2d/549/141/","by":{"1":"12"}},{"t":"case","label":"Swaby v. Yates","cite":"847 F.3d 62","y":2017,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/847/62/","by":{"1":"34"}},{"t":"case","label":"United States v. Aguila-Montes de Oca","cite":"655 F.3d 915","y":2011,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/655/915/","by":{"1":"18"}},{"t":"case","label":"United States v. Brumback","cite":"614 F. App’x 288","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/614/288/","by":{"1":"33"}},{"t":"case","label":"United States v. Faulls","cite":"821 F.3d 502","y":2016,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/821/502/","by":{"1":"18"}},{"t":"case","label":"United States v. Granderson","cite":"511 U.S. 39","y":1994,"id":"1993/92-1662","sc":1,"sum":"The Court held 7-2 that the U.S. Code's section 3565 refers to the original sentence range set by U.S. Sentencing Guidelines. Therefore, the minimum revocation sentence for drug possession while on probation is one third the maximum of the Guidelines range of imprisonment; the maximum revocation sentence is the Guidelines maximum.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"United States v. Henriquez","cite":"757 F.3d 144","y":2014,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/757/144/","sum":"Holding Maryland’s burglary statute is nongeneric because it “covers burglaries of motor vehicles or boats – places the United States Supreme Court has expressly excluded from generic burglary.”.","sumSrc":"brief:2","by":{"1":"35","2":"22"}},{"t":"case","label":"United States v. Rainer","cite":"616 F.3d 1212","y":2010,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/616/1212/","by":{"1":"29"}},{"t":"case","label":"United States v. Stevens","cite":"559 U.S. 460","y":2010,"id":"2009/08-769","sc":1,"sum":"The Court ruled that 18 U.S.C. Section 48 was unconstitutional under the Free Speech Clause of the First Amendment.","sumSrc":"Oyez","by":{"1":"31"}},{"t":"case","label":"United States v. Thomas","cite":"2017 WL 6375741","y":2017,"court":"E.D.N.Y. Dec. 13","sum":"Noting that the categorical approach can be taxing on both courts and litigants because it requires “a legalistic assessment of a vast universe of statutes of conviction that are as varied as the states that enact them”.","sumSrc":"brief:1","by":{"1":"19"}},{"t":"case","label":"United States v. Woods","cite":"571 U.S. 31","y":2013,"id":"2013/12-562","sc":1,"sum":"The Court held that, under the Tax Equity and Fiscal Responsibility Act of 1982, a court in partnership-level proceedings has the right to consider the applicability of any penalty that relates to the partnership.","sumSrc":"Oyez","by":{"1":"33"}},{"t":"case","label":"Vasquez v. Sessions","cite":"138 S. Ct. 2697","y":2018,"url":"https://www.courtlistener.com/c/S.%20Ct./138/2697/","sc":1,"by":{"1":"35"}},{"t":"case","label":"Vasquez v. Sessions","cite":"885 F.3d 862","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/885/862/","by":{"1":"35"}},{"t":"case","label":"Vassell v. U.S. Att’y Gen.","cite":"839 F.3d 1352","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/839/1352/","by":{"1":"35"}},{"t":"case","label":"Wash. State Grange v. Wash. State Republican Party","cite":"552 U.S. 442","y":2008,"id":"2007/06-713","sc":1,"sum":"The Court reversed the Ninth Circuit's ruling and held the party affiliation provision constitutional. Writing for the majority, Justice Clarence Thomas explained that the state law never referred to the candidates as nominees of any particular party.","sumSrc":"Oyez","by":{"1":"32"}},{"t":"case","label":"Watson v. United States","cite":"552 U.S. 74","y":2007,"id":"2007/06-571","sc":1,"by":{"1":"17"}},{"t":"case","label":"Whyte v. Lynch","cite":"807 F.3d 463","y":2015,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/807/463/","by":{"1":"38"}},{"t":"usc","label":"18 U.S.C. § 48","url":"https://www.law.cornell.edu/uscode/text/18/48","subs":["(c)"],"by":{"1":"31"}},{"t":"reg","label":"24 C.F.R. pt. 3280","url":"https://www.ecfr.gov/current/title-24/part-3280","by":{"1":"11"}},{"t":"reg","label":"24 C.F.R. pt. 3282","url":"https://www.ecfr.gov/current/title-24/part-3282","by":{"1":"11"}},{"t":"reg","label":"81 Fed. Reg. 6806","url":"https://www.govinfo.gov/link/fr/81/6806","by":{"1":"11"}},{"t":"case","label":"California v. Fleetwood","cite":"171 Cal. App. 3d 982","y":1985,"court":"Ct. App.","url":"https://www.courtlistener.com/c/Cal.%20App.%203d/171/982/","ar":1,"by":{"2":"32"}},{"t":"case","label":"Chambers v. United States","cite":"555 U.S. 122","y":2009,"id":"2008/06-11206","sc":1,"sum":"The Court found that the \"failure to report\" crime does not satisfy the Armed Career Criminals Act's (ACCA) \"crime of violence\" definition.","sumSrc":"Oyez","by":{"2":"29"}},{"t":"case","label":"Dickerson v. New Banner Institute, Inc.","cite":"460 U.S. 103","y":1983,"id":"1982/81-1180","sc":1,"sum":"The firearms disabilities imposed by §§ 922(g)(1) and (h)(1) apply to Kennison and were not removed by the expunction of the record of his guilty plea to the concealed weapon charge.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"10"}},{"t":"case","label":"Patterson v. McLean Credit Union","cite":"491 U.S. 164","y":1989,"id":"scdb/1988-115","sc":1,"sum":"Petitioner, a black woman, was employed by respondent credit union as a teller and file coordinator for 10 years until she was laid off. Thereafter, she brought this action in District Court under 42 U. S. C. § 1981, alleging that respondent had harassed her, failed to promote her to accounting clerk, and then discharged her, all because of her race. The District Court determined that a claim for racial harassment …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"30"}},{"t":"case","label":"Cited Authorities Page Payne v. Tennessee","cite":"501 U.S. 808","y":1991,"id":"1990/90-5721","sc":1,"sum":"The Court reasoned that since \"[v]irtually no limits are placed on the relevant mitigating evidence a capital defendant may introduce concerning his own circumstances,\" the prosecution must be allowed to submit similar counter evidence.","sumSrc":"Oyez","by":{"2":"30"}},{"t":"case","label":"Price v. Texas","cite":"2002 WL 471343","y":2002,"court":"Tex. App. Mar. 28","by":{"2":"32"}},{"t":"case","label":"State v. Thompson","cite":"2015 WL 1756448","y":2015,"court":"Tenn. Crim. App. Apr. 15","by":{"2":"34"}},{"t":"case","label":"United States v. Bennett","cite":"100 F.3d 1105","y":1996,"court":"3rd Cir.","url":"https://www.courtlistener.com/c/F.3d/100/1105/","sum":"Holding Pennsylvania’s burglary statute is broader than generic because it “includes within its definition of occupied structure any vehicle adapted for overnight accommodations or for business.”.","sumSrc":"brief:2","by":{"2":"22"}},{"t":"case","label":"United States v. Gundy","cite":"842 F.3d 1156","y":2016,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/842/1156/","by":{"2":"22"}},{"t":"case","label":"United States v. Howard","cite":"742 F.3d 1334","y":2014,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/742/1334/","sum":"Holding Alabama’s burglary statute is not generic because “[a] number of [ ] things included in the definition of ‘building’ (such as vehicles and watercraft) fall outside the ‘building or structure’ element of generic burglary.”.","sumSrc":"brief:2","by":{"2":"22"}},{"t":"case","label":"United States v. Lara","cite":"590 F. App’x 574","y":2014,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/590/574/","by":{"2":"34"}},{"t":"case","label":"United States v. Moncrief","cite":"356 F. App’x 11","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/356/11/","sum":"Finding Tennessee’s aggravated burglary statute nongeneric but a violent felony under the ACCA’s residual clause.","sumSrc":"brief:2","by":{"2":"29"}},{"t":"case","label":"United States v. Narvarro","cite":"584 F. App’x 624","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/584/624/","by":{"2":"20"}},{"t":"case","label":"United States v. Naylor","cite":"887 F.3d 397","y":2018,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/887/397/","by":{"2":"26"}},{"t":"case","label":"United States v. Robinson","cite":"720 F. App’x 946","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.%20App%E2%80%99x/720/946/","by":{"2":"23"}},{"t":"case","label":"United States v. Silva","cite":"957 F.2d 157","y":1992,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/957/157/","by":{"2":"23"}},{"t":"case","label":"Cited Authorities Page United States v. Sparks","cite":"265 F.3d 825","y":2001,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/265/825/","by":{"2":"32"}},{"t":"case","label":"United States v. Stitt","cite":"860 F.3d 854","y":2017,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/860/854/","op":2,"by":{"2":"12, 14, 30, 33"}},{"t":"case","label":"United States v. Sweeten","cite":"933 F.2d 765","y":1991,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.2d/933/765/","by":{"2":"23"}},{"t":"const","label":"Amendment V","clauses":[["grand-jury","Grand Jury Clause"],["double-jeopardy","Double Jeopardy Clause"],["self-incrimination","Self-Incrimination Clause"],["due-process-5","Due Process Clause (Fifth Amendment)"],["takings","Takings Clause"]],"text":"No person shall be held to answer for a capital, or otherwise infamous crime, unless on a presentment or indictment of a Grand Jury, except in cases arising in the land or naval forces, or in the Militia, when in actual service in time of War or public danger; nor shall any person be subject for the same offence to be twice put in jeopardy of life or limb; nor shall be compelled in any criminal case to be a witness against himself, nor be deprived of life, liberty, or property, without due process of law; nor shall private property be taken for public use, without just compensation.","by":{"2":"6, 31"}},{"t":"const","label":"Amendment VI","clauses":[["sixth-trial","Speedy and Public Trial by Jury"],["confrontation","Confrontation Clause"],["counsel","Right to Counsel"]],"text":"In all criminal prosecutions, the accused shall enjoy the right to a speedy and public trial, by an impartial jury of the State and district wherein the crime shall have been committed, which district shall have been previously ascertained by law, and to be informed of the nature and cause of the accusation; to be confronted with the witnesses against him; to have compulsory process for obtaining witnesses in his favor, and to have the Assistance of Counsel for his defence.","by":{"2":"7, 35"}},{"t":"usc","label":"18 U.S.C. § 1202","url":"https://www.law.cornell.edu/uscode/text/18/1202","subs":["(c)(9)"],"by":{"2":"7, 7"}},{"t":"case","label":"Bowen v. Massachusetts","cite":"487 U.S. 879","y":1988,"id":"1987/87-712","sc":1,"sum":"The federal contribution (referred to as a \"reimbursement\") to a State's Medicaid program takes the form of advances based on the State's estimate of its future expenditures for covered services. Overpayments may be withheld from future advances, or, if a disallowance dispute develops, may be retained by the State at its option pending resolution of the dispute. After Massachusetts was reimbursed by the Department …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17"}},{"t":"case","label":"Bruesewitz v. Wyeth LLC","cite":"562 U.S. 223","y":2011,"id":"2010/09-152","sc":1,"sum":"The Court held that the National Childhood Vaccine Injury Act shielded manufacturers from certain product liability lawsuits that seek damages for serious health problems suffered by children.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Carachuri-Rosendo v. Holder","cite":"560 U.S. 563","y":2010,"id":"2009/09-60","sc":1,"sum":"The Court held that a minor drug offense is not automatic grounds for deportation of a legal immigrant.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"(I) Cases—Continued: Elk Grove Unified Sch. Dist. v. Newdow","cite":"542 U.S. 1","y":2004,"id":"2003/02-1624","sc":1,"sum":"The Court held that a divorced father did not have sufficient custody of his daughter to challenge the Establishment Clause of the First Amendment on her behalf.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Kimble v. Marvel Ent’mt, LLC","cite":"135 S. Ct. 2401","y":2015,"id":"2014/13-720","sc":1,"sum":"The Court determined that its earlier decision in Brulotte v. Thys Co. , which held that a patentee cannot continue to receive royalties after the expiration of the patent, should be upheld.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"case","label":"Maracich v. Spears","cite":"570 U.S. 48","y":2013,"id":"2012/12-25","sc":1,"sum":"The Court found that lawyers may use personal information protected by the Driver's Privacy Protection Act to find potential plaintiffs for a group action.","sumSrc":"Oyez","by":{"3":"15"}},{"t":"case","label":"Scheidler v. National Org. for Women, Inc.","cite":"537 U.S. 393","y":2003,"id":"2002/01-1118","sc":1,"sum":"The Court held that abortion opponents did not commit extortion because they did not \"obtain\" property from the abortion supporters as required by the Hobbs Act. The Court further held that is first holding renders insufficient the other bases or predicate acts of racketeering supporting the jury's conclusion that the abortion opponents violated RICO.","sumSrc":"Oyez","by":{"3":"9"}},{"t":"case","label":"Southern Union Co. v. United States","cite":"567 U.S. 343","y":2012,"id":"2011/11-94","sc":1,"sum":"The Court held that the rule applied in Apprendi v. New Jersey, where the Sixth Amendment’s guarantee of a jury trial requires that any fact which increases the maximum punishment for a particular crime be proved to a jury, applies to the imposition of criminal fines.","sumSrc":"Oyez","by":{"3":"19"}},{"t":"case","label":"United States v. Castleman","cite":"572 U.S. 157","y":2014,"id":"2013/12-1371","sc":1,"sum":"The Court held that a Tennessee man's conviction of domestic violence under state law also prevented him from legally possessing firearms under federal law.","sumSrc":"Oyez","by":{"3":"7"}},{"t":"case","label":"United States v. Gaudin","cite":"515 U.S. 506","y":1995,"id":"1994/94-514","sc":1,"sum":"The trial judge's refusal to submit the question of \"materiality\" to the jury was unconstitutional.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"15"}},{"t":"case","label":"United States v. Tinklenberg","cite":"563 U.S. 647","y":2011,"id":"2010/09-1498","sc":1,"sum":"The Court held that the time between the filing of a pretrial motion and its disposition is excluded from the deadline for commencing trial under the Speedy Trial Act.","sumSrc":"Oyez","by":{"3":"16"}},{"t":"usc","label":"8 U.S.C. § 1101","url":"https://www.law.cornell.edu/uscode/text/8/1101","subs":["(a)(43)(A)"],"by":{"3":"4"}}]};